/* @autogenerated */
import { DestroyRef, inject, Injectable, Signal, signal, WritableSignal } from '@angular/core';
import { defaultIfEmpty, firstValueFrom, Observable } from 'rxjs';
import { rootLogger } from '@shared/context/observability/logger.service';
import { markErrorHandled } from '@shared/context/observability/error.service';
import { NotifyService } from '@shared/toolkit/notify/notify.service';
import { parseCell } from './cell-parse';
import {
  ImportDefinition,
  ImportJob,
  ImportMessage,
  ImportOutcome,
  ImportPlan,
  ImportRow,
  ImportRowResult,
} from './entity-import.model';

const JOB_PREFIX = 'entity-import-job-';
const PLAN_PREFIX = 'entity-import-plan-';
/** Cada cuánto renueva el latido la pestaña que ejecuta la importación. */
const HEARTBEAT_MS = 5_000;
/** Sin latido durante este tiempo, la importación se da por interrumpida (se cerró la pestaña que la ejecutaba). */
const STALE_MS = 90_000;
/** Como mucho una escritura del estado por este intervalo mientras avanza. */
const PERSIST_MS = 1_000;

/** Lo que se necesita para seguir: filas, columnas y permisos; se guarda una vez al empezar. */
type StoredPlan = Omit<ImportPlan, 'fileName'>;

/**
 * Ejecuta las importaciones fuera de la pantalla que las lanza: siguen al cerrarla o navegar, y su estado se
 * guarda en `localStorage` por `storageKey`. Al volver (en otra pantalla, pestaña o sesión) se consulta el estado;
 * si la pestaña que la ejecutaba se cerró, queda interrumpida y se puede reanudar desde la primera fila pendiente
 * salvo que lleve columnas sensibles, que no se guardan.
 *
 * Cada fila se busca por su clave natural: si existe se actualiza y si no se crea.
 */
@Injectable({ providedIn: 'root' })
export class EntityImportService {
  private readonly notify = inject(NotifyService);
  private readonly jobs = new Map<string, WritableSignal<ImportJob | null>>();
  /** Importaciones que ejecuta esta pestaña, con su marca de cancelación. */
  private readonly controls = new Map<string, { cancelled: boolean }>();
  private readonly runningKeys = signal<ReadonlySet<string>>(new Set());

  constructor() {
    // Lo que escribe otra pestaña llega por el evento `storage`
    const onStorage = (event: StorageEvent) => {
      const key = event.key?.startsWith(JOB_PREFIX) ? event.key.substring(JOB_PREFIX.length) : null;
      if (key && !this.controls.has(key)) {
        this.jobs.get(key)?.set(this.revive(key, readStored<ImportJob>(JOB_PREFIX + key)));
      }
    };
    // Al recargar o cerrar la pestaña, lo que estaba en marcha aquí queda interrumpido
    const onHide = () =>
      this.controls.forEach((_, key) => {
        const job = this.jobs.get(key)?.();
        if (job?.status === 'running') {
          writeStored(JOB_PREFIX + key, { ...job, status: 'interrupted' });
        }
      });
    window.addEventListener('storage', onStorage);
    window.addEventListener('pagehide', onHide);
    inject(DestroyRef).onDestroy(() => {
      window.removeEventListener('storage', onStorage);
      window.removeEventListener('pagehide', onHide);
    });
  }

  /** Estado de la importación `key`, o `null` si no hay ninguna. */
  job(key: string): Signal<ImportJob | null> {
    return this.jobSignal(key).asReadonly();
  }

  /** La importación `key` la está ejecutando esta pestaña (y se puede cancelar desde aquí). */
  isRunningHere(key: string): boolean {
    return this.runningKeys().has(key);
  }

  /** Vuelve a leer el estado: detecta las importaciones de otra pestaña que han dejado de latir. */
  refresh(key: string): void {
    if (!this.controls.has(key)) {
      this.jobSignal(key).set(this.revive(key, readStored<ImportJob>(JOB_PREFIX + key)));
    }
  }

  canResume(key: string): boolean {
    const job = this.jobSignal(key)();
    return (
      !!job &&
      job.resumable &&
      (job.status === 'interrupted' || job.status === 'cancelled') &&
      job.processed < job.total &&
      !this.controls.has(key)
    );
  }

  start<T>(definition: ImportDefinition<T>, plan: ImportPlan): void {
    const key = definition.storageKey;
    if (this.controls.has(key)) {
      throw new Error(`There is already an import running for ${key}`);
    }
    const { fileName, ...stored } = plan;
    removeStored(PLAN_PREFIX + key);
    const resumable = !plan.sensitive && writeStored(PLAN_PREFIX + key, stored);
    const now = new Date().toISOString();
    const job: ImportJob = {
      key,
      fileName,
      status: 'running',
      startedAt: now,
      updatedAt: now,
      total: plan.rows.length,
      processed: 0,
      created: 0,
      updated: 0,
      failed: 0,
      warned: 0,
      outcomes: [],
      resumable,
    };
    this.run(definition, stored, job);
  }

  /** Sigue una importación interrumpida o cancelada desde la primera fila pendiente. */
  resume<T>(definition: ImportDefinition<T>): void {
    const key = definition.storageKey;
    const job = this.jobSignal(key)();
    const stored = readStored<StoredPlan>(PLAN_PREFIX + key);
    if (!job || !stored || !this.canResume(key)) {
      throw new Error(`There is no import to resume for ${key}`);
    }
    this.run(definition, stored, { ...job, status: 'running', finishedAt: undefined });
  }

  /** Se para antes de la siguiente fila; lo ya guardado se queda. */
  cancel(key: string): void {
    const control = this.controls.get(key);
    if (control) {
      control.cancelled = true;
    }
  }

  /** Olvida la importación terminada para poder empezar otra. */
  clear(key: string): void {
    if (this.controls.has(key)) {
      throw new Error(`Unable to clear the running import ${key}`);
    }
    removeStored(JOB_PREFIX + key);
    removeStored(PLAN_PREFIX + key);
    this.jobSignal(key).set(null);
  }

  private async run<T>(definition: ImportDefinition<T>, plan: StoredPlan, initial: ImportJob): Promise<void> {
    const key = definition.storageKey;
    const control = { cancelled: false };
    const state = this.jobSignal(key);
    this.controls.set(key, control);
    this.runningKeys.update((keys) => new Set(keys).add(key));

    let job = initial;
    let persisted = 0;
    const publish = (force = false) => {
      job = { ...job, updatedAt: new Date().toISOString() };
      state.set(job);
      if (force || Date.now() - persisted >= PERSIST_MS) {
        persisted = Date.now();
        writeStored(JOB_PREFIX + key, job);
      }
    };
    publish(true);
    const heartbeat = setInterval(() => publish(true), HEARTBEAT_MS);
    try {
      for (let index = job.processed; index < plan.rows.length; index++) {
        if (control.cancelled) {
          break;
        }
        const outcome = await this.processRow(definition, plan, plan.rows[index]);
        job.outcomes.push(outcome);
        job = { ...job, processed: index + 1, [outcome.result]: job[outcome.result] + 1 };
        if (outcome.result !== 'failed' && outcome.messages?.length) {
          job = { ...job, warned: (job.warned ?? 0) + 1 };
        }
        publish();
      }
      job = { ...job, status: control.cancelled ? 'cancelled' : 'finished', finishedAt: new Date().toISOString() };
    } catch (error) {
      rootLogger.error('Import interrupted', error);
      job = { ...job, status: 'interrupted' };
    } finally {
      clearInterval(heartbeat);
      this.controls.delete(key);
      this.runningKeys.update((keys) => {
        const copy = new Set(keys);
        copy.delete(key);
        return copy;
      });
      if (job.status === 'finished') {
        removeStored(PLAN_PREFIX + key);
        job = { ...job, resumable: false };
      }
      publish(true);
    }
    const params = { created: String(job.created), updated: String(job.updated), failed: String(job.failed) };
    if (job.failed) {
      this.notify.error('common.import.notify.' + job.status, params);
    } else if (job.warned) {
      this.notify.info('common.import.notify.' + job.status, params);
    } else {
      this.notify.success('common.import.notify.' + job.status, params);
    }
  }

  private async processRow<T>(
    definition: ImportDefinition<T>,
    plan: StoredPlan,
    row: ImportRow,
  ): Promise<ImportOutcome> {
    const values: Record<string, unknown> = {};
    // Campos de solo lectura: se aplican con su acción una vez guardado el elemento
    const desired: Record<string, Desired> = {};
    const messages: ImportMessage[] = [];
    for (const column of plan.columns) {
      const parsed = parseCell(row.cells[column.index], column);
      if ('error' in parsed) {
        messages.push(parsed.error);
      } else if (parsed.value !== undefined && column.type === 'reference') {
        const ref = await this.reference(definition, column.field, String(parsed.value));
        if (ref) {
          values[column.field] = ref;
        } else {
          messages.push({
            key: 'common.import.error.reference',
            params: { field: column.label, value: String(parsed.value) },
          });
        }
      } else if (parsed.value !== undefined) {
        if (column.viaAction) {
          desired[column.field] = { value: parsed.value, text: String(row.cells[column.index]).trim() };
        } else {
          values[column.field] = parsed.value;
        }
      }
    }
    const item = values as Partial<T>;
    const display = definition.display
      ? definition.display(item)
      : definition.keys.map((field) => values[field] ?? '').join(' · ');
    const failed = (...reasons: ImportMessage[]): ImportOutcome => ({
      row: row.row,
      display,
      result: 'failed',
      messages: reasons,
    });
    if (messages.length) {
      return failed(...messages);
    }
    const emptyKeys = plan.columns.filter((c) => definition.keys.includes(c.field) && values[c.field] === undefined);
    if (emptyKeys.length) {
      return failed({
        key: 'common.import.error.missingKey',
        params: { fields: emptyKeys.map((c) => c.label).join(', ') },
      });
    }
    try {
      const found = await once(definition.target.find(item), []);
      if (found.length > 1) {
        return failed({ key: 'common.import.error.ambiguous', params: { count: String(found.length) } });
      }
      if (found.length === 1) {
        if (!plan.canUpdate) {
          return failed({ key: 'common.import.error.notAllowed.update' });
        }
        const saved = await once(definition.target.update({ ...found[0], ...item }), null);
        return this.saved(row, display, 'updated', await this.applyActions(definition, plan, saved, desired));
      }
      if (!plan.canCreate) {
        return failed({ key: 'common.import.error.notAllowed.create' });
      }
      const missing = [
        ...plan.missingRequired,
        ...plan.columns.filter((c) => c.required && values[c.field] === undefined).map((c) => c.label),
      ];
      if (missing.length) {
        return failed({ key: 'common.import.error.missingRequired', params: { fields: missing.join(', ') } });
      }
      const saved = await once(definition.target.add({ ...(definition.defaults?.() ?? {}), ...item } as T), null);
      return this.saved(row, display, 'created', await this.applyActions(definition, plan, saved, desired));
    } catch (error) {
      // El fallo queda en el resumen de la fila: sin el aviso global por cada una
      markErrorHandled(error);
      return failed(...serverMessages(error));
    }
  }

  private saved(row: ImportRow, display: string, result: ImportRowResult, warnings: ImportMessage[]): ImportOutcome {
    return warnings.length ? { row: row.row, display, result, messages: warnings } : { row: row.row, display, result };
  }

  /**
   * Lleva cada campo de solo lectura al valor del Excel con la acción que lo deja en él, si el elemento guardado no lo
   * tiene ya. Lo que no se puede aplicar (no hay acción, no hay permiso o falla) queda como aviso de la fila.
   */
  private async applyActions<T>(
    definition: ImportDefinition<T>,
    plan: StoredPlan,
    saved: T | null,
    desired: Record<string, Desired>,
  ): Promise<ImportMessage[]> {
    const warnings: ImportMessage[] = [];
    let current = saved;
    for (const [field, { value, text }] of Object.entries(desired)) {
      if (!current || (current as Record<string, unknown>)[field] === value) {
        continue;
      }
      const column = plan.columns.find((c) => c.field === field)!;
      const params = { field: column.label, value: text };
      const action = definition.actions?.[field]?.find((candidate) => candidate.value === value);
      if (!action) {
        warnings.push({ key: 'common.import.warn.noAction', params });
      } else if (!plan.allowedActions.includes(action.name)) {
        warnings.push({ key: 'common.import.warn.notAllowed', params: { ...params, action: action.name } });
      } else {
        try {
          current = await once(action.run(current), current);
        } catch (error) {
          markErrorHandled(error);
          warnings.push(
            ...serverMessages(error).map((message) => ({
              key: 'common.import.warn.actionFailed',
              params: { ...params, action: action.name, message: message.params?.['message'] ?? '' },
            })),
          );
        }
      }
    }
    return warnings;
  }

  private async reference<T>(definition: ImportDefinition<T>, field: string, text: string) {
    const resolver = definition.references?.[field];
    return resolver ? once(resolver.resolve(text), null) : null;
  }

  private jobSignal(key: string): WritableSignal<ImportJob | null> {
    let job = this.jobs.get(key);
    if (!job) {
      job = signal(this.revive(key, readStored<ImportJob>(JOB_PREFIX + key)));
      this.jobs.set(key, job);
    }
    return job;
  }

  /** Una importación "en curso" que no ejecuta esta pestaña y ha dejado de latir está interrumpida. */
  private revive(key: string, job: ImportJob | null): ImportJob | null {
    if (job?.status === 'running' && !this.controls.has(key) && Date.now() - Date.parse(job.updatedAt) > STALE_MS) {
      const interrupted: ImportJob = { ...job, status: 'interrupted' };
      writeStored(JOB_PREFIX + key, interrupted);
      return interrupted;
    }
    return job;
  }
}

/** Valor que pide el Excel para un campo de solo lectura, y el texto de la celda para los avisos. */
interface Desired {
  value: unknown;
  text: string;
}

/** Primer valor del observable (los del repositorio no completan), o `fallback` si completa sin emitir. */
function once<V>(source: Observable<V>, fallback: V): Promise<V> {
  return firstValueFrom(source.pipe(defaultIfEmpty(fallback)));
}

/** Mensajes del cuerpo del error: una lista de violaciones, un texto o el mensaje del propio error. */
function serverMessages(error: any): ImportMessage[] {
  const status = error?.status ? String(error.status) : '';
  const body = error?.error;
  const texts: string[] = Array.isArray(body)
    ? body.map((item: any) =>
        typeof item === 'string'
          ? item
          : [item?.field, item?.description ?? item?.message ?? item?.code].filter((part) => !!part).join(': '),
      )
    : [typeof body === 'string' ? body : (body?.message ?? body?.detail ?? body?.title ?? error?.message ?? '')];
  return texts.map((message) => ({ key: 'common.import.error.server', params: { status, message } }));
}

function readStored<V>(storageKey: string): V | null {
  try {
    const raw = localStorage.getItem(storageKey);
    return raw === null ? null : (JSON.parse(raw) as V);
  } catch {
    rootLogger.warn(`Ignoring unreadable import state ${storageKey}`);
    return null;
  }
}

/** Devuelve si se ha podido guardar (sin cuota o en modo privado el estado sigue solo en memoria). */
function writeStored(storageKey: string, value: unknown): boolean {
  try {
    localStorage.setItem(storageKey, JSON.stringify(value));
    return true;
  } catch {
    rootLogger.warn(`Unable to persist import state ${storageKey}`);
    return false;
  }
}

function removeStored(storageKey: string): void {
  try {
    localStorage.removeItem(storageKey);
  } catch {
    // Nada que borrar si no hay almacenamiento
  }
}
